sp_widget.client_script:
api.controller = function($location) {

    var c = this;


    /*
     * ==========================================
     * VARIABLES
     * ==========================================
     */

    c.loading = true;

    c.documents = [];

    c.errorMessage = "";


    /*
     * ==========================================
     * LOAD DOCUMENTS
     * ==========================================
     */

    c.loadDocuments = function() {

        c.loading = true;

        c.errorMessage = "";

        c.server.get({

            action: "get_documents"

        }).then(function(response) {

            c.loading = false;

            if (
                response.data.success === true
            ) {

                c.documents =
                    response.data.documents || [];

            } else {

                c.documents = [];

                c.errorMessage =
                    response.data.message ||
                    "Unable to load documents.";

            }

        }, function() {

            c.loading = false;

            c.documents = [];

            c.errorMessage =
                "Unable to connect to the document service.";

        });

    };


    /*
     * ==========================================
     * COUNT BY STATUS
     * ==========================================
     */

    c.getCount = function(status) {

        var count = 0;

        angular.forEach(
            c.documents,
            function(document) {

                if (
                    document.validation_status ==
                    status
                ) {

                    count++;

                }

            }
        );

        return count;
    };


    /*
     * ==========================================
     * VIEW DOCUMENT
     * ==========================================
     */

    c.viewDocument = function(document) {

        if (
            !document ||
            !document.attachment_sys_id
        ) {

            return;
        }


        var url =
            "/sys_attachment.do?sys_id=" +
            encodeURIComponent(
                document.attachment_sys_id
            );


        window.open(
            url,
            "_blank"
        );

    };


    /*
     * ==========================================
     * HOME
     * ==========================================
     */

    c.goHome = function() {

        $location.search({

            id: "claim_home"

        });

    };


    /*
     * ==========================================
     * SUBMIT CLAIM
     * ==========================================
     */

    c.goToSubmitClaim = function() {

        $location.search({

            id: "submit_claim"

        });

    };


    /*
     * ==========================================
     * INITIAL LOAD
     * ==========================================
     */

    c.loadDocuments();

};

sp_widget.css:
/* =========================================================
   INSURANCE CLAIM HUB - DOCUMENTS
   ========================================================= */

.ich-documents-page {
    max-width: 1200px;
    margin: 0 auto;
    padding: 35px 25px 60px;
    font-family: "Inter", "Segoe UI", Arial, sans-serif;
    color: #17324d;
}


/* =========================================================
   HEADER
   ========================================================= */

.ich-documents-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 25px;

    padding-bottom: 25px;
    margin-bottom: 25px;

    border-bottom: 1px solid #dce7f2;
}

.ich-header-left {
    display: flex;
    align-items: center;
    gap: 16px;
}

.ich-header-icon {
    width: 58px;
    height: 58px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 16px;

    background: linear-gradient(
        135deg,
        #e9f3ff,
        #d7eaff
    );

    font-size: 27px;

    box-shadow:
        0 8px 20px rgba(20, 94, 160, 0.12);
}

.ich-eyebrow {
    display: block;

    margin-bottom: 5px;

    color: #1976d2;

    font-size: 10px;
    font-weight: 800;

    letter-spacing: 1.4px;
}

.ich-documents-header h1 {
    margin: 0;

    color: #0b3b67;

    font-size: 30px;
    font-weight: 800;
}

.ich-documents-header p {
    margin: 6px 0 0;

    color: #6b8195;

    font-size: 13px;
}


/* =========================================================
   BUTTONS
   ========================================================= */

.ich-header-actions {
    display: flex;
    gap: 10px;
}

.ich-btn {
    border: none;
    border-radius: 8px;

    padding: 10px 17px;

    font-size: 12px;
    font-weight: 700;

    cursor: pointer;

    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        background 0.2s ease;
}

.ich-btn:hover {
    transform: translateY(-1px);
}

.ich-btn-primary {
    color: #ffffff;

    background: linear-gradient(
        135deg,
        #087ff5,
        #075fc4
    );

    box-shadow:
        0 6px 16px rgba(8, 127, 245, 0.22);
}

.ich-btn-primary:hover {
    background: linear-gradient(
        135deg,
        #096fe0,
        #064fa7
    );
}

.ich-btn-secondary {
    color: #1261a0;

    background: #ffffff;

    border: 1px solid #b9d5ed;
}

.ich-btn-secondary:hover {
    background: #f1f8ff;
}


/* =========================================================
   LOADING
   ========================================================= */

.ich-loading-card {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 13px;

    padding: 45px;

    background: #ffffff;

    border: 1px solid #dce7f2;
    border-radius: 14px;

    color: #52708a;

    font-size: 13px;

    box-shadow:
        0 5px 20px rgba(21, 67, 100, 0.07);
}

.ich-spinner {
    width: 22px;
    height: 22px;

    border: 3px solid #d7e8f8;
    border-top-color: #087ff5;

    border-radius: 50%;

    animation: ich-spin 0.8s linear infinite;
}

@keyframes ich-spin {
    to {
        transform: rotate(360deg);
    }
}


/* =========================================================
   SUMMARY
   ========================================================= */

.ich-summary {
    display: grid;

    grid-template-columns:
        repeat(4, 1fr);

    gap: 15px;

    margin-bottom: 22px;
}

.ich-summary-card {
    display: flex;
    align-items: center;
    gap: 13px;

    padding: 18px;

    background: #ffffff;

    border: 1px solid #dce7f2;

    border-radius: 12px;

    box-shadow:
        0 5px 18px rgba(21, 67, 100, 0.06);
}

.ich-summary-icon {
    width: 42px;
    height: 42px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 11px;

    background: #eaf4ff;

    color: #087ff5;

    font-size: 18px;
}

.ich-summary-icon.approved {
    background: #e8f8ef;
    color: #159447;
}

.ich-summary-icon.pending {
    background: #fff6dc;
    color: #d98b00;
}

.ich-summary-icon.rejected {
    background: #ffebeb;
    color: #d63d3d;
}

.ich-summary-card span {
    display: block;

    color: #7a8fa2;

    font-size: 11px;
}

.ich-summary-card strong {
    display: block;

    margin-top: 3px;

    color: #123d63;

    font-size: 21px;
}


/* =========================================================
   TABLE CARD
   ========================================================= */

.ich-table-card {
    overflow: hidden;

    background: #ffffff;

    border: 1px solid #dce7f2;

    border-radius: 14px;

    box-shadow:
        0 8px 25px rgba(21, 67, 100, 0.08);
}

.ich-table-header {
    padding: 20px 22px;

    border-bottom: 1px solid #e5edf5;

    background:
        linear-gradient(
            135deg,
            #ffffff,
            #f5faff
        );
}

.ich-table-header h2 {
    margin: 0;

    color: #123f68;

    font-size: 17px;
    font-weight: 800;
}

.ich-table-header p {
    margin: 5px 0 0;

    color: #7890a5;

    font-size: 11px;
}


/* =========================================================
   TABLE
   ========================================================= */

.ich-table-wrapper {
    width: 100%;

    overflow-x: auto;
}

.ich-document-table {
    width: 100%;

    border-collapse: collapse;

    font-size: 12px;
}

.ich-document-table thead {
    background: #f4f8fc;
}

.ich-document-table th {
    padding: 14px 15px;

    text-align: left;

    color: #55718a;

    font-size: 10px;
    font-weight: 800;

    text-transform: uppercase;

    letter-spacing: 0.5px;

    border-bottom: 1px solid #dce7f2;
}

.ich-document-table td {
    padding: 15px;

    vertical-align: middle;

    color: #38566f;

    border-bottom: 1px solid #edf2f7;
}

.ich-document-table tbody tr {
    transition:
        background 0.2s ease;
}

.ich-document-table tbody tr:hover {
    background: #f7fbff;
}

.ich-document-table tbody tr:last-child td {
    border-bottom: none;
}


/* =========================================================
   CLAIM NUMBER
   ========================================================= */

.ich-claim-number {
    display: inline-block;

    padding: 5px 8px;

    border-radius: 6px;

    background: #edf6ff;

    color: #086bc7;

    font-weight: 800;

    font-size: 11px;
}


/* =========================================================
   DOCUMENT NAME
   ========================================================= */

.ich-document-name {
    display: flex;
    align-items: center;
    gap: 9px;

    min-width: 180px;
}

.ich-file-icon {
    width: 30px;
    height: 30px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 7px;

    background: #eef6ff;

    font-size: 14px;
}

.ich-document-name strong {
    color: #234c6d;

    font-size: 12px;
}


/* =========================================================
   DOCUMENT TYPE
   ========================================================= */

.ich-type {
    color: #5c7489;

    font-size: 11px;
}


/* =========================================================
   STATUS
   ========================================================= */

.ich-status {
    display: inline-flex;
    align-items: center;
    gap: 5px;

    padding: 6px 10px;

    border-radius: 20px;

    font-size: 10px;
    font-weight: 800;
}

.status-approved {
    color: #147a3d;

    background: #e7f8ed;
}

.status-pending {
    color: #a66a00;

    background: #fff4d7;
}

.status-rejected {
    color: #b72f2f;

    background: #ffe9e9;
}


/* =========================================================
   REJECTION
   ========================================================= */

.ich-rejection {
    display: block;

    max-width: 190px;

    color: #bd3838;

    font-size: 10px;

    line-height: 1.5;
}

.ich-no-rejection {
    color: #a6b4c0;
}


/* =========================================================
   VIEW BUTTON
   ========================================================= */

.ich-view-btn {
    padding: 8px 13px;

    border: none;

    border-radius: 7px;

    color: #ffffff;

    background: linear-gradient(
        135deg,
        #0b83e6,
        #075db4
    );

    font-size: 10px;
    font-weight: 800;

    cursor: pointer;

    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease;
}

.ich-view-btn:hover {
    transform: translateY(-1px);

    box-shadow:
        0 5px 12px rgba(7, 93, 180, 0.25);
}

.ich-no-file {
    color: #9aaab8;

    font-size: 10px;
}


/* =========================================================
   EMPTY
   ========================================================= */

.ich-empty-card {
    padding: 60px 30px;

    text-align: center;

    background: #ffffff;

    border: 1px solid #dce7f2;

    border-radius: 14px;

    box-shadow:
        0 8px 25px rgba(21, 67, 100, 0.07);
}

.ich-empty-icon {
    width: 65px;
    height: 65px;

    display: flex;
    align-items: center;
    justify-content: center;

    margin: 0 auto 15px;

    border-radius: 50%;

    background: #edf6ff;

    font-size: 27px;
}

.ich-empty-card h2 {
    margin: 0;

    color: #153f64;

    font-size: 19px;
}

.ich-empty-card p {
    margin: 8px 0 20px;

    color: #7b91a4;

    font-size: 12px;
}


/* =========================================================
   ERROR
   ========================================================= */

.ich-message {
    padding: 15px 18px;

    border-radius: 10px;

    font-size: 12px;
}

.ich-error {
    color: #a52828;

    background: #fff0f0;

    border: 1px solid #f0c7c7;
}


/* =========================================================
   INFORMATION
   ========================================================= */

.ich-info-box {
    display: flex;
    gap: 12px;

    margin-top: 20px;

    padding: 15px 18px;

    background: #eef7ff;

    border-left: 4px solid #087ff5;

    border-radius: 8px;
}

.ich-info-icon {
    color: #087ff5;

    font-size: 16px;
}

.ich-info-box strong {
    color: #245273;

    font-size: 11px;
}

.ich-info-box p {
    margin: 4px 0 0;

    color: #668198;

    font-size: 10px;

    line-height: 1.5;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 900px) {

    .ich-summary {
        grid-template-columns:
            repeat(2, 1fr);
    }

    .ich-documents-header {
        align-items: flex-start;

        flex-direction: column;
    }

}


@media (max-width: 600px) {

    .ich-documents-page {
        padding: 20px 12px 40px;
    }

    .ich-summary {
        grid-template-columns: 1fr;
    }

    .ich-header-actions {
        width: 100%;
    }

    .ich-btn {
        flex: 1;
    }

}

sp_widget.script:
(function() {

    data.success = false;
    data.documents = [];
    data.message = "";

    if (!input ||
        input.action != "get_documents") {

        return;
    }

    try {

        /*
         * ==========================================
         * CURRENT LOGGED-IN USER
         * ==========================================
         */

        var currentUser =
            gs.getUser();

        var userEmail =
            currentUser.getEmail();

        if (!userEmail) {

            data.message =
                "Unable to identify the logged-in customer.";

            return;
        }


        /*
         * ==========================================
         * FIND POLICYHOLDER
         * ==========================================
         */

        var policyholder =
            new GlideRecord(
                "x_snc_insurance_0_policyholder"
            );

        policyholder.addQuery(
            "email",
            userEmail
        );

        policyholder.setLimit(1);
        policyholder.query();


        if (!policyholder.next()) {

            data.success = true;

            data.message =
                "No policyholder record is linked to this account.";

            return;
        }


        var policyholderSysId =
            policyholder.getUniqueValue();


        /*
         * ==========================================
         * FIND CUSTOMER CLAIMS
         * ==========================================
         */

        var claim =
            new GlideRecord(
                "x_snc_insurance_0_claim"
            );

        claim.addQuery(
            "policyholder",
            policyholderSysId
        );

        claim.query();


        var claimIds = [];

        while (claim.next()) {

            claimIds.push(
                claim.getUniqueValue()
            );

        }


        if (claimIds.length === 0) {

            data.success = true;

            return;
        }


        /*
         * ==========================================
         * FIND CLAIM DOCUMENTS
         * ==========================================
         */

        var document =
            new GlideRecord(
                "x_snc_insurance_0_claim_document"
            );

        document.addQuery(
            "claim",
            "IN",
            claimIds.join(",")
        );

        document.orderByDesc(
            "sys_created_on"
        );

        document.query();


        while (document.next()) {

            var claimSysId =
                document.getValue("claim");

            var claimNumber = "";


            /*
             * Get claim number
             */

            if (claimSysId) {

                var claimRecord =
                    new GlideRecord(
                        "x_snc_insurance_0_claim"
                    );

                if (claimRecord.get(claimSysId)) {

                    claimNumber =
                        claimRecord.getValue(
                            "claim_number"
                        ) || "";

                }

            }


            /*
             * ======================================
             * FIND ATTACHMENT
             * ======================================
             */

            var attachmentSysId = "";

            var attachment =
                new GlideRecord(
                    "sys_attachment"
                );

            attachment.addQuery(
                "table_name",
                "x_snc_insurance_0_claim_document"
            );

            attachment.addQuery(
                "table_sys_id",
                document.getUniqueValue()
            );

            attachment.orderByDesc(
                "sys_created_on"
            );

            attachment.setLimit(1);

            attachment.query();


            if (attachment.next()) {

                attachmentSysId =
                    attachment.getUniqueValue();

            }


            /*
             * ======================================
             * ADD DOCUMENT
             * ======================================
             */

            data.documents.push({

                sys_id:
                    document.getUniqueValue(),

                claim_number:
                    claimNumber,

                document_name:
                    document.getValue(
                        "document_name"
                    ) || "",

                document_type:
                    document.getDisplayValue(
                        "document_type"
                    ) || "",

                validation_status:
                    document.getDisplayValue(
                        "document_validation_status"
                    ) || "Pending",

                rejection_reason:
                    document.getValue(
                        "rejection_reason"
                    ) || "",

                attachment_sys_id:
                    attachmentSysId

            });

        }


        data.success = true;


    } catch (e) {

        data.success = false;

        data.message =
            "Unable to load documents: " +
            e.message;

    }

})();
